import React, { useState } from 'react';
import {
  AppBar,
  Box,
  Button,
  Chip,
  Drawer,
  IconButton,
  List,
  ListItemButton,
  ListItemIcon,
  ListItemText,
  Stack,
  Toolbar,
  Typography,
  useMediaQuery,
  useTheme,
} from '@mui/material';
import {
  Article as BlogIcon,
  FactCheck as FactorIcon,
  HealthAndSafety as HealthIcon,
  Hub as IntegrationIcon,
  Logout as LogoutIcon,
  Menu as MenuIcon,
  People as PeopleIcon,
  Settings as PlatformIcon,
  Speed as OcrIcon,
  Store as RegistryIcon,
  Tune as AutomationIcon,
} from '@mui/icons-material';
import { useLocation, useNavigate } from 'react-router-dom';
import BrandLogoMark from '../BrandLogoMark';
import {
  formatOrganizationType,
  getPortalRoleLabel,
} from '../../constants/adminPortal';
import { SIDEBAR_WIDTH } from '../../constants/appNavigation';
import { APP_CONTENT_GUTTER } from '../../constants/appShellLayout';
import { getAdminPortalUser } from '../../utils/adminPortalSession';
import { useRegistration } from '../../context/RegistrationContext';
import { isViewRoleProfile } from '../../utils/authRole';
import {
  SIDEBAR_WORKSPACE_BACKGROUND,
  SIDEBAR_WORKSPACE_BORDER,
  SIDEBAR_WORKSPACE_TEXT_PRIMARY,
  SIDEBAR_WORKSPACE_TEXT_SECONDARY,
} from '../../theme';
import ReviewerReadOnlyBanner from './ReviewerReadOnlyBanner';

export interface AdminCrumb {
  label: string;
  onClick?: () => void;
}

interface AdminNavItem {
  label: string;
  path: string;
  icon: React.ReactNode;
  adminOnly?: boolean;
  match: (pathname: string, search: string) => boolean;
}

interface AdminNavGroup {
  id: string;
  label: string;
  items: AdminNavItem[];
}

const GROUPS: AdminNavGroup[] = [
  {
    id: 'registry',
    label: 'Registry',
    items: [
      {
        label: 'Company registry',
        path: '/admin/dashboard',
        icon: <RegistryIcon fontSize="small" />,
        match: (pathname, search) => (
          (pathname === '/admin/dashboard' && !search.includes('section='))
          || pathname.startsWith('/admin/msme/')
        ),
      },
      {
        label: 'Emission factors',
        path: '/admin/emission-factors',
        icon: <FactorIcon fontSize="small" />,
        adminOnly: true,
        match: (pathname) => pathname === '/admin/emission-factors',
      },
    ],
  },
  {
    id: 'people',
    label: 'People',
    items: [
      {
        label: 'Expert and support users',
        path: '/admin/dashboard?section=people',
        icon: <PeopleIcon fontSize="small" />,
        adminOnly: true,
        match: (pathname, search) => pathname === '/admin/dashboard' && search.includes('section=people'),
      },
    ],
  },
  {
    id: 'platform',
    label: 'Platform',
    items: [
      {
        label: 'Features and billing',
        path: '/admin/dashboard?section=platform',
        icon: <PlatformIcon fontSize="small" />,
        adminOnly: true,
        match: (pathname, search) => pathname === '/admin/dashboard' && search.includes('section=platform'),
      },
      {
        label: 'Integrations',
        path: '/admin/integrations',
        icon: <IntegrationIcon fontSize="small" />,
        match: (pathname) => pathname === '/admin/integrations',
      },
    ],
  },
  {
    id: 'content',
    label: 'Content',
    items: [
      {
        label: 'Blog',
        path: '/admin/blog-articles',
        icon: <BlogIcon fontSize="small" />,
        match: (pathname) => pathname === '/admin/blog-articles',
      },
    ],
  },
  {
    id: 'operations',
    label: 'Operations',
    items: [
      {
        label: 'OCR benchmarks',
        path: '/admin/ocr-benchmarks',
        icon: <OcrIcon fontSize="small" />,
        adminOnly: true,
        match: (pathname) => pathname === '/admin/ocr-benchmarks',
      },
      {
        label: 'OCR automation',
        path: '/admin/ocr-automation',
        icon: <AutomationIcon fontSize="small" />,
        adminOnly: true,
        match: (pathname) => pathname === '/admin/ocr-automation',
      },
      {
        label: 'System health',
        path: '/admin/system-health',
        icon: <HealthIcon fontSize="small" />,
        adminOnly: true,
        match: (pathname) => pathname === '/admin/system-health',
      },
    ],
  },
];

interface AdminPortalLayoutProps {
  title: string;
  subtitle?: string;
  breadcrumbs?: AdminCrumb[];
  children: React.ReactNode;
  maxWidth?: 'lg' | 'xl' | false;
}

const AdminPortalLayout: React.FC<AdminPortalLayoutProps> = ({
  title,
  subtitle,
  breadcrumbs = [],
  children,
}) => {
  const theme = useTheme();
  const isDesktop = useMediaQuery(theme.breakpoints.up('md'));
  const [mobileOpen, setMobileOpen] = useState(false);
  const navigate = useNavigate();
  const location = useLocation();
  const { logout } = useRegistration();
  const portalUser = getAdminPortalUser();
  const isReviewer = isViewRoleProfile();
  const displayName = [portalUser?.profile?.firstName, portalUser?.profile?.lastName]
    .filter(Boolean)
    .join(' ')
    .trim();
  const organizationLabel = formatOrganizationType(portalUser?.accessCredentials?.organizationType);

  const go = (path: string) => {
    navigate(path);
    setMobileOpen(false);
  };

  const sidebar = (
    <Box sx={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
      <Box sx={{ px: 2, py: 2 }}>
        <Box sx={{ bgcolor: 'background.paper', borderRadius: 1, p: 1 }}>
          <BrandLogoMark width={150} />
        </Box>
        <Typography variant="overline" sx={{ display: 'block', mt: 1, color: SIDEBAR_WORKSPACE_TEXT_SECONDARY, letterSpacing: 1.2 }}>
          Admin workspace
        </Typography>
      </Box>
      <List sx={{ px: 1, flex: 1, overflow: 'auto' }}>
        {GROUPS.map((group) => {
          const items = group.items.filter((item) => !isReviewer || !item.adminOnly);
          if (items.length === 0) return null;
          return (
            <Box key={group.id} sx={{ mb: 1 }}>
              <Typography variant="overline" sx={{ px: 1.5, color: SIDEBAR_WORKSPACE_TEXT_SECONDARY, letterSpacing: 1 }}>
                {group.label}
              </Typography>
              {items.map((item) => {
                const active = item.match(location.pathname, location.search);
                return (
                  <ListItemButton
                    key={item.path}
                    selected={active}
                    aria-current={active ? 'page' : undefined}
                    onClick={() => go(item.path)}
                    sx={{
                      mb: 0.25,
                      borderRadius: 1,
                      color: active ? '#fff' : SIDEBAR_WORKSPACE_TEXT_PRIMARY,
                      backgroundColor: active ? 'rgba(76, 175, 80, 0.28)' : 'transparent',
                      '&:hover': { backgroundColor: active ? 'rgba(76, 175, 80, 0.34)' : 'rgba(255, 255, 255, 0.06)' },
                      '&:focus-visible': { outline: '2px solid #ffffff', outlineOffset: 2 },
                    }}
                  >
                    <ListItemIcon sx={{ minWidth: 36, color: 'inherit' }}>{item.icon}</ListItemIcon>
                    <ListItemText primary={item.label} primaryTypographyProps={{ fontSize: 14, fontWeight: active ? 700 : 500 }} />
                  </ListItemButton>
                );
              })}
            </Box>
          );
        })}
      </List>
    </Box>
  );

  return (
    <Box sx={{ display: 'flex', minHeight: '100vh', bgcolor: 'background.default' }}>
      <Drawer
        variant={isDesktop ? 'permanent' : 'temporary'}
        open={isDesktop || mobileOpen}
        onClose={() => setMobileOpen(false)}
        ModalProps={{ keepMounted: true }}
        sx={{
          width: isDesktop ? SIDEBAR_WIDTH : 0,
          flexShrink: 0,
          '& .MuiDrawer-paper': {
            width: SIDEBAR_WIDTH,
            boxSizing: 'border-box',
            bgcolor: SIDEBAR_WORKSPACE_BACKGROUND,
            color: SIDEBAR_WORKSPACE_TEXT_PRIMARY,
            borderRight: `1px solid ${SIDEBAR_WORKSPACE_BORDER}`,
          },
        }}
      >
        {sidebar}
      </Drawer>
      <Box sx={{ flex: 1, minWidth: 0, display: 'flex', flexDirection: 'column' }}>
        <AppBar position="static" color="default" elevation={0} sx={{ borderBottom: 1, borderColor: 'divider', bgcolor: 'background.paper' }}>
          <Toolbar sx={{ gap: 1, flexWrap: 'wrap', py: 1 }}>
            {isDesktop ? null : (
              <IconButton aria-label="Open navigation" edge="start" onClick={() => setMobileOpen(true)}>
                <MenuIcon />
              </IconButton>
            )}
            <Box sx={{ flexGrow: 1, minWidth: 160 }}>
              <Typography variant="body2" sx={{ fontWeight: 700 }}>
                {displayName || portalUser?.email || 'Signed in'}
              </Typography>
              <Typography variant="caption" color="text.secondary">
                {isReviewer ? 'Reviewer portal' : 'Admin portal'}
              </Typography>
            </Box>
            <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap" useFlexGap>
              <Chip size="small" color={isReviewer ? 'info' : 'primary'} label={getPortalRoleLabel(portalUser?.role)} />
              {portalUser?.accessCredentials?.organizationName ? (
                <Chip size="small" variant="outlined" label={portalUser.accessCredentials.organizationName} />
              ) : null}
              <Chip size="small" variant="outlined" label={organizationLabel} />
              <Button size="small" color="inherit" startIcon={<LogoutIcon />} onClick={() => logout({ redirectTo: '/login' })}>
                Logout
              </Button>
            </Stack>
          </Toolbar>
        </AppBar>
        <Box component="main" sx={{ flex: 1, px: APP_CONTENT_GUTTER, py: { xs: 2, md: 3 }, overflow: 'auto' }}>
          {breadcrumbs.length > 0 ? (
            <Stack direction="row" spacing={0.75} alignItems="center" flexWrap="wrap" useFlexGap sx={{ mb: 1 }} aria-label="Breadcrumb">
              {breadcrumbs.map((crumb, index) => (
                <React.Fragment key={`${crumb.label}-${index}`}>
                  {index > 0 ? <Typography variant="body2" color="text.secondary">/</Typography> : null}
                  {crumb.onClick ? (
                    <Button size="small" onClick={crumb.onClick} sx={{ minWidth: 0, px: 0.5 }}>{crumb.label}</Button>
                  ) : (
                    <Typography variant="body2" color="text.secondary">{crumb.label}</Typography>
                  )}
                </React.Fragment>
              ))}
            </Stack>
          ) : null}
          <Typography component="h1" variant="h4" sx={{ fontWeight: 700, fontSize: { xs: '1.5rem', md: '2rem' } }}>
            {title}
          </Typography>
          {subtitle ? (
            <Typography variant="body1" color="text.secondary" sx={{ mt: 0.5, mb: 2, maxWidth: 760 }}>
              {subtitle}
            </Typography>
          ) : <Box sx={{ mb: 2 }} />}
          {isReviewer ? <ReviewerReadOnlyBanner /> : null}
          {children}
        </Box>
      </Box>
    </Box>
  );
};

export default AdminPortalLayout;
